mapper.update:
update REP_FEE_TRD


        PAID_FEE = #{paidFee,jdbcType=DECIMAL},


        ACCRUAL = #{accrual,jdbcType=DECIMAL},


        STATUS = #{status,jdbcType=VARCHAR},


        UPDATE_USER = #{createUser,jdbcType=VARCHAR},


        UPDATE_TIME = #{updateTime,jdbcType=TIMESTAMP},


where PROD_ID = #{prodId,jdbcType=CHAR}
  and PAY_DATE = #{payDate,jdbcType=DATE}
  and FEE_TYPE = #{feeType,jdbcType=CHAR}

mapper.delete:
		update REP_FEE_TRD
		set STATUS = 'D'
		where PROD_ID = #{prodId,jdbcType=CHAR}
          and PAY_DATE = #{payDate,jdbcType=DATE}
          and FEE_TYPE = #{feeType,jdbcType=CHAR}

mapper.select:
select rft.PROD_ID prodId, rpi.PROD_NAME prodName, rft.PAY_DATE payDate, rft.FEE_TYPE feeType, rft.PAID_FEE paidFee, rft.ACCRUAL accrual, rft.STATUS status, rft.UPDATE_USER updateUser, rft.UPDATE_TIME updateTime, cie.ERR_MSG errmsg from REP_FEE_TRD rft left join REP_PROD_INFO rpi on rpi.PROD_ID = rft.PROD_ID left join CHB_INTERF_ERRODATA cie on cie.DATAID = rft.PROD_ID and cie.INTERF_TYPE = 'CHB_PRD_FEE_DEAL'
and rft.PROD_ID = #{prodId,jdbcType=VARCHAR}
and rft.FEE_TYPE = #{feeType,jdbcType=VARCHAR}
and rft.PAY_DATE >= to_date(#{startDate,jdbcType=DATE},'yyyy-MM-dd')
and rft.PAY_DATE <= to_date(#{endDate,jdbcType=DATE},'yyyy-MM-dd')
and rft.STATUS = #{status,jdbcType=VARCHAR}
